<?php
declare(strict_types=1);
use Bulbula\Core\Csrf;
use Bulbula\Core\View;
?>
<div class="b-grid" style="grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:var(--space-5)">
<section class="b-card" style="padding:var(--space-6)"><span class="b-badge b-badge--orange">Personal details</span><h2 style="margin:var(--space-3) 0">Staff profile</h2><p class="b-text-muted" style="font-size:var(--text-sm)">You may update your own identity details. Role and account status remain Administrator-managed.</p>
<form method="POST" action="/staff/profile" style="display:grid;gap:var(--space-4);margin-top:var(--space-5)"><?= Csrf::field() ?><div><label class="b-label" for="staff-name">Full name</label><input id="staff-name" class="b-input" name="full_name" value="<?= View::e($staff['full_name'] ?? '') ?>" maxlength="120" required></div><div><label class="b-label" for="staff-email">Sign-in email</label><input id="staff-email" class="b-input" type="email" name="email" value="<?= View::e($staff['email'] ?? '') ?>" autocomplete="email" required></div><div><label class="b-label" for="staff-profile-password">Current password confirmation</label><input id="staff-profile-password" class="b-input" type="password" name="current_password" autocomplete="current-password" required></div><div><label class="b-label" for="staff-profile-totp">Authenticator code <span style="font-weight:400">(required when changing email)</span></label><input id="staff-profile-totp" class="b-input" name="current_totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"></div><button class="b-btn b-btn--primary" type="submit">Save profile</button></form></section>
<section class="b-card" style="padding:var(--space-6)"><span class="b-badge b-badge--verified">Security</span><h2 style="margin:var(--space-3) 0">Change password</h2><p class="b-text-muted" style="font-size:var(--text-sm)">Use 12–128 characters with uppercase, lowercase, and a number.</p>
<form method="POST" action="/staff/profile/password" style="display:grid;gap:var(--space-4);margin-top:var(--space-5)" autocomplete="off"><?= Csrf::field() ?><div><label class="b-label" for="staff-current-password">Current password</label><input id="staff-current-password" class="b-input" type="password" name="current_password" autocomplete="current-password" required></div><div><label class="b-label" for="staff-new-password">New password</label><input id="staff-new-password" class="b-input" type="password" name="new_password" minlength="12" maxlength="128" autocomplete="new-password" required></div><div><label class="b-label" for="staff-confirm-password">Confirm new password</label><input id="staff-confirm-password" class="b-input" type="password" name="new_password_confirmation" minlength="12" maxlength="128" autocomplete="new-password" required></div><button class="b-btn b-btn--primary" type="submit">Change password</button></form></section>
<section class="b-card" style="padding:var(--space-6);display:block"><span class="b-badge">Authenticator</span><h2 style="margin:var(--space-3) 0">Two-factor protection</h2><p class="b-text-muted" style="font-size:var(--text-sm)">Your account is <?= !empty($staff['totp_enabled']) ? 'protected by an authenticator app' : 'waiting for authenticator enrollment' ?>. Replacement requires both your password and a current code.</p>
<?php if(!empty($pendingAuthenticator)): ?><div class="b-alert b-alert--info"><strong>New authenticator secret</strong><br><code style="user-select:all;word-break:break-all"><?= View::e($pendingAuthenticator['secret']) ?></code><p style="font-size:var(--text-xs)">Add this secret manually in your authenticator app. The existing authenticator remains valid until the new code is confirmed.</p></div><form method="POST" action="/staff/profile/authenticator/confirm" style="display:flex;gap:var(--space-2);margin-top:var(--space-4)"><?= Csrf::field() ?><input class="b-input" name="new_totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="New six-digit code" required><button class="b-btn b-btn--primary b-btn--sm" type="submit">Confirm replacement</button></form>
<?php else: ?><form method="POST" action="/staff/profile/authenticator/replace" style="display:grid;gap:var(--space-3);margin-top:var(--space-4)" autocomplete="off"><?= Csrf::field() ?><div><label class="b-label" for="totp-password">Current password</label><input id="totp-password" class="b-input" type="password" name="current_password" autocomplete="current-password" required></div><div><label class="b-label" for="current-totp">Current authenticator code</label><input id="current-totp" class="b-input" name="current_totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required></div><button class="b-btn b-btn--outline b-btn--sm" type="submit">Replace authenticator</button></form><?php endif; ?>
<dl style="display:grid;grid-template-columns:auto 1fr;gap:var(--space-2) var(--space-4);font-size:var(--text-sm);margin-top:var(--space-4)"><dt>Role</dt><dd><?= View::e(ucfirst(strtolower((string)($staff['role'] ?? '')))) ?></dd><dt>Last sign-in</dt><dd><?= View::e((string)($staff['last_login_at'] ?? 'Not recorded')) ?></dd></dl></section>
<section class="b-card" style="padding:var(--space-6);display:block"><span class="b-badge b-badge--verified">Active sessions</span><h2 style="margin:var(--space-3) 0">Signed-in devices</h2><?php foreach($activeSessions as $device): ?><div style="display:flex;justify-content:space-between;align-items:center;gap:1rem;padding:.7rem 0;border-top:1px solid var(--neutral-100)"><div><strong><?= View::e($device['device_label']) ?></strong><div style="font-size:var(--text-xs);color:var(--neutral-500)"><?= !empty($device['is_current'])?'This device · ':'' ?><?= View::e($device['last_seen_at']) ?></div></div><?php if(empty($device['is_current'])): ?><form method="POST" action="/staff/profile/sessions/<?= (int)$device['id'] ?>/revoke"><?= Csrf::field() ?><button class="b-btn b-btn--outline b-btn--sm" type="submit">Sign out</button></form><?php endif; ?></div><?php endforeach; ?><form method="POST" action="/staff/profile/sessions/others/revoke" style="margin-top:var(--space-3)"><?= Csrf::field() ?><button class="b-btn b-btn--outline b-btn--sm" type="submit">Sign out all other devices</button></form></section>
<section class="b-card" style="padding:var(--space-6);display:block"><span class="b-badge">Security activity</span><h2 style="margin:var(--space-3) 0">Recent account events</h2><?php if(empty($securityEvents)): ?><p class="b-text-muted" style="font-size:var(--text-sm)">No security events recorded yet.</p><?php else: ?><ul style="list-style:none;padding:0;margin:0;display:grid;gap:var(--space-3)"><?php foreach($securityEvents as $event): ?><li style="display:flex;justify-content:space-between;gap:var(--space-3);font-size:var(--text-sm);border-top:1px solid var(--neutral-100);padding-top:var(--space-3)"><strong><?= View::e(ucwords(strtolower(str_replace('_',' ',(string)$event['action_code'])))) ?></strong><time style="color:var(--neutral-500)"><?= View::e((string)$event['created_at']) ?></time></li><?php endforeach; ?></ul><?php endif; ?></section>
</div>
